            <button onclick="window.print()">Imprimir</button>
        </div>
    </header>

    <main class="cv-container">
        <aside class="cv-sidebar">
            <h1>Sergio Jurado</h1>
            <h2>Operario de Logística</h2>
            <div class="contact-mini">
