## 2️⃣ Header (`src/components/Header.astro`)

```astro
---
import { ui } from '../data/resume';
const { lang } = Astro.props;
const t = ui[lang];
const base = '/resume';
const prefix = lang === 'es' ? '' : `/${lang}`;
const links = [
  { href: `${base}${prefix}/`, label: t.home },
  { href: `${base}${prefix}/about`, label: t.about },
  { href: `${base}${prefix}/services`, label: t.services },
  { href: `${base}${prefix}/shop`, label: t.shop },
  { href: `${base}${prefix}/contact`, label: t.contact },
];
---
<header class="site-header">
  <nav>
    <a href="/resume/" class="logo">senseikatana<span class="muted">/resume</span></a>
    <ul>
      {links.map(l => <li><a href={l.href}>{l.label}</a></li>)}
    </ul>
    <div class="tools">
      <div class="lang-switcher">
        <a href="/resume/" class={lang==='es'?'active':''}>ES</a>
        <a href="/resume/ca/" class={lang==='ca'?'active':''}>CA</a>
        <a href="/resume/en/" class={lang==='en'?'active':''}>EN</a>
      </div>
      <button id="theme-toggle" aria-label="Theme">🌓</button>
    </div>
  </nav>
</header>

<style>
  .site-header {
    border-bottom: 1px solid var(--border);
    background: color-mix(in srgb, var(--bg) 88%, transparent);
    backdrop-filter: blur(10px);
    position: sticky; top: 0; z-index: 10;
    padding: .9rem 1.5rem;
  }
  nav { max-width: 860px; margin: 0 auto; display: flex; align-items: center; gap: 1.5rem; flex-wrap: wrap; }
  .logo { font-weight: 700; font-family: var(--mono); color: var(--text); }
  ul { list-style: none; padding: 0; display: flex; gap: 1.1rem; flex: 1; flex-wrap: wrap; }
  ul a { color: var(--text); font-size: .95rem; font-weight: 400; }
  .tools { display: flex; align-items: center; gap: .75rem; }
  .lang-switcher { display: flex; gap: .4rem; font-size: .85rem; }
  .lang-switcher a {
    color: var(--muted); padding: .15rem .5rem; border-radius: 6px;
    border: 1px solid transparent;
  }
  .lang-switcher a.active {
    color: var(--accent); border-color: var(--accent); font-weight: 700;
  }
  #theme-toggle {
    background: var(--surface-2); border: 1px solid var(--border);
    border-radius: 50%; width: 38px; height: 38px; font-size: 1rem;
    color: var(--text); cursor: pointer;
  }
  @media (max-width: 640px) { ul { order: 3; width: 100%; } }
</style>

<script>
  document.getElementById('theme-toggle')?.addEventListener('click', () => {
    const h = document.documentElement;
    const next = h.dataset.theme === 'dark' ? 'light' : 'dark';
    h.dataset.theme = next;
    localStorage.setItem('theme', next);
  });
</script>
```

