### 3. Layout Global (`src/layouts/Layout.astro`)
```astro
---
export interface Props { title: string; lang: string; }
const { title, lang } = Astro.props;
---
<html lang={lang} data-theme="light">
<head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>{title}</title>
    <style is:global>
        :root { --bg: #f8f9fa; --text: #212529; --card: #ffffff; --border: #dee2e6; --accent: #0d6efd; }
        [data-theme="dark"] { --bg: #121212; --text: #e9ecef; --card: #1e1e1e; --border: #333; --accent: #4dabf7; }
        body { font-family: system-ui, sans-serif; background: var(--bg); color: var(--text); margin: 0; transition: background 0.3s; }
        .container { max-width: 1000px; margin: 0 auto; padding: 2rem; }
        .top-bar { display: flex; justify-content: space-between; align-items: center; margin-bottom: 2rem; font-size: 0.9rem; }
        .top-bar a { color: var(--text); text-decoration: none; margin: 0 0.5rem; }
        .top-bar button { background: none; border: 1px solid var(--border); color: var(--text); padding: 0.25rem 0.75rem; border-radius: 4px; cursor: pointer; }
        .card { background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 2rem; box-shadow: 0 4px 6px rgba(0,0,0,0.05); }

        @media print {
            .top-bar, .no-print { display: none !important; }
            body { background: white; color: black; }
            .card { box-shadow: none; border: none; padding: 0; }
        }
    </style>
</head>
<body>
    <div class="container">
        <slot />
    </div>
    <script is:inline>
        // Botón de impresión y tema oscuro simple
        document.addEventListener('click', (e) => {
            if (e.target.id === 'print-btn') window.print();
            if (e.target.id === 'theme-btn') {
                const html = document.documentElement;
                html.dataset.theme = html.dataset.theme === 'dark' ? 'light' : 'dark';
            }
        });
    </script>
</body>
</html>
