            {data.edu.map((e: any) => (
                <div class="edu-item">
                    <strong>{e.t}</strong>
                    <span>{e.d}</span>
                </div>
            ))}
        </aside>

        <section class="main-content">
            <h2>{data.title}</h2>
            <p class="desc">{data.desc}</p>

            <h3>{t.about}</h3>
            <p>{data.about}</p>

            <h3>{t.experience}</h3>
            {data.exp.map((e: any) => (
                <div class="exp-item">
                    <div class="exp-header">
                        <strong>{e.t}</strong> <span class="company">@ {e.c}</span>
                        <span class="date">{e.d}</span>
                    </div>
                    <ul>{e.b.map((b: string) => <li>{b}</li>)}</ul>
                </div>
            ))}

            <h3>{t.projects}</h3>
            <div class="projects">
                {data.proj.map((p: any) => (
                    <a href={p.u} class="proj-card" target="_blank">
                        <strong>{p.t}</strong>
                        <p>{p.d}</p>
                        <span>{t.viewGithub} →</span>
                    </a>
                ))}
            </div>
        </section>
    </main>
</Layout>

<style>
